mapper.select:
SELECT ktp.id 'id', kc.class_name 'className', ktp.plan_url 'planUrl', ktp.begin_date 'beginDate', kks.name 'name', ktp.create_time 'createTime' FROM kg_teaching_program ktp INNER JOIN kg_classroom kc ON kc.id = ktp.class_id INNER JOIN kg_kindergarten_staff kks ON kks.uid = ktp.create_by WHERE ktp.kg_id = #{queryVO.kgId} AND ktp.del_flag = 0
AND ktp.begin_date = DATE_FORMAT(#{queryVO.beginDate},'%Y-%m-%d')
AND ktp.class_id = #{queryVO.classId}
